import dask.array as da
import xarray as xr
import numpy as np
import dask.config

class CustomScheduler:
    def __init__(self, max_computes=1):
        self.max_computes = max_computes
        self.computes = 0

    def __call__(self, dsk, keys, **kwargs):
        self.computes += 1
        if self.computes > self.max_computes:
            raise RuntimeError(f"Too many dask computations were scheduled: {self.computes}")
        # Use the default scheduler for the actual computation
        from dask.scheduling import default_scheduler
        return default_scheduler(dsk, keys, **kwargs)

def test_da_where_triggers_compute():
    d1 = da.from_array(np.random.random((10, 10)), chunks=(5, 5))
    d2 = da.from_array(np.random.random((10, 10)), chunks=(5, 5))
    xr1 = xr.DataArray(d1)
    xr2 = xr.DataArray(d2)

    with dask.config.set(scheduler=CustomScheduler(max_computes=0)):
        try:
            da.where(xr1 > 0.5, xr2, np.nan)
            print("da.where did not trigger compute")
        except RuntimeError as e:
            print(f"da.where triggered compute: {e}")
            return True
    return False

if __name__ == "__main__":
    if test_da_where_triggers_compute():
        print("Reproduction successful: da.where triggered compute")
        exit(0)
    else:
        print("Reproduction failed: da.where did not trigger compute")
        exit(1)

